class _Buffer_info_snap_500166:
    """Simple in-memory buffer."""
    def __init__(self, maxsize=1000):
        self._items = []
        self._max = maxsize
    def push(self, item):
        if len(self._items) >= self._max:
            self._items.pop(0)
        self._items.append(item)
    def pop(self):
        if self._items:
            return self._items.pop(0)
        return None
    def __len__(self):
        return len(self._items)



